export const PROGRAM_LANGUAGES=[['htmlcss','HTML e CSS'],['python','Python'],['csharp','C#']];
export function validateProgramming(p){if(!p||!PROGRAM_LANGUAGES.some(([id])=>id===p.language)||!['live','button','off'].includes(p.validation)||typeof p.preview!=='boolean'||typeof p.autocomplete!=='boolean')throw Error('Confira linguagem e recursos da avaliação de programação.');for(const field of ['starterHtml','starterCss','starterCode'])if(typeof p[field]!=='string'||p[field].length>20000)throw Error('Código inicial com até 20.000 caracteres por arquivo.');if(p.preview&&p.language!=='htmlcss')throw Error('A prévia é disponível somente para HTML/CSS.');return p;}
export function validateProgrammingAnswer(language,value){if(language==='htmlcss'){if(!value||typeof value!=='object'||Array.isArray(value)||Object.keys(value).some(k=>!['html','css'].includes(k))||typeof value.html!=='string'||typeof value.css!=='string'||value.html.length>20000||value.css.length>20000||!value.html.trim()&&!value.css.trim())throw Error('Preencha HTML e/ou CSS (até 20.000 caracteres por arquivo).');return {html:value.html,css:value.css};}if(!['python','csharp'].includes(language)||typeof value!=='string'||!value.trim()||value.length>20000)throw Error('Preencha o código (até 20.000 caracteres).');return value;}
export function programmingText(value){if(value&&typeof value==='object'&&typeof value.html==='string'&&typeof value.css==='string')return 'HTML\n'+value.html+'\n\nCSS\n'+value.css;return String(value??'');}
